const groupRoleDefinitions={creator:{label:'Content creators',functions:['content.create'],description:'Create and submit drafts for the selected channels.'},approver:{label:'Content approvers',functions:['content.approve'],description:'Review and approve content for the selected channels.'},ads:{label:'Ad managers',functions:['ads.create','ads.manage'],description:'Manage advertising drafts for explicitly selected ad accounts.'}};
function assignmentsForUser(user){return user?assetsData.groups.flatMap(g=>(g.userAssignments||[]).filter(a=>a.userId===user.id).map(a=>({...a,groupId:g.id}))):[]}
function effectiveFunctionAccess(user,functionId){return Boolean(user&&(user.functions.includes(functionId)||assignmentsForUser(user).some(a=>groupRoleDefinitions[a.role]?.functions.includes(functionId))))}
function effectiveAccountAccess(user,channelId){return Boolean(user&&(user.channels.includes(channelId)||assignmentsForUser(user).some(a=>a.role!=='ads'&&a.channelIds.includes(channelId)&&assetsData.channels.some(c=>c.id===channelId&&c.assetGroup===a.groupId))))}
function scopedGroupGrant(assignments,functionId,resourceType,resourceId){return assignments.some(a=>Boolean(groupRoleDefinitions[a.role]?.functions.includes(functionId)&&(resourceType==='channels'?a.role!=='ads'&&a.channelIds.includes(resourceId):resourceType==='adAccounts'?a.role==='ads'&&a.adAccountIds.includes(resourceId):false)))}
const directAccountFunction=hasAccountFunction;hasAccountFunction=function(user,functionId,resourceType,resourceId){if(directAccountFunction(user,functionId,resourceType,resourceId))return true;if(!user)return false;return scopedGroupGrant(assignmentsForUser(user).filter(a=>resourceType!=='channels'||assetsData.channels.some(c=>c.id===resourceId&&c.assetGroup===a.groupId)),functionId,resourceType,resourceId)};
const groupViewBeforePeople=showAssetGroups;showAssetGroups=function(){groupViewBeforePeople();const tabs=document.querySelector('.asset-tabs');if(!tabs||!assetsData.groups.some(g=>g.id===assetsData.selected))return;const button=document.createElement('button');button.textContent='People & access';button.dataset.assetPeople='true';button.classList.toggle('active',assetTab==='people');button.onclick=()=>{assetTab='people';showAssetGroups()};tabs.append(button);if(assetTab==='people')renderGroupPeople()};
function renderGroupPeople(){const g=assetsData.groups.find(g=>g.id===assetsData.selected);if(!g)return;g.userAssignments=g.userAssignments||[];document.querySelectorAll('.asset-tabs button').forEach(b=>b.classList.toggle('active',Boolean(b.dataset.assetPeople)));document.querySelector('.asset-body').innerHTML=`<div class="asset-section-title"><div><h3>People & access</h3><p>Assignments here are scoped to this Asset Group and the accounts explicitly selected.</p></div></div><div class="voice-cards">${Object.entries(groupRoleDefinitions).map(([role,def])=>`<article><h4>${def.label}</h4><p>${def.description}</p>${g.userAssignments.filter(a=>a.role===role).map(a=>`<div class="row"><div class="grow"><strong>${safe(accessUsers.find(u=>u.id===a.userId)?.name||'Unknown user')}</strong><small>${role==='ads'?a.adAccountIds.length+' ad accounts':a.channelIds.length+' channels'} assigned</small></div>${can('assets.manage')?`<button class="btn" data-remove-group-user="${a.id}">Remove</button>`:''}</div>`).join('')||'<p class="ops-muted">No users assigned.</p>'}${can('assets.manage')?`<button class="btn primary" data-add-group-users="${role}">＋ Add user(s)</button>`:''}</article>`).join('')}</div><p class="ops-muted">Newly linked channels are not granted automatically. Removing a role removes only its group-scoped grants, not the user’s independent permissions. Ad managers receive no social-channel access from this role.</p>`;document.querySelectorAll('[data-add-group-users]').forEach(b=>b.onclick=()=>addGroupUsers(b.dataset.addGroupUsers));document.querySelectorAll('[data-remove-group-user]').forEach(b=>b.onclick=()=>{if(!can('assets.manage'))return;g.userAssignments=g.userAssignments.filter(a=>a.id!==b.dataset.removeGroupUser);persistAssets();logOps('Asset-group user role removed',g.name);renderGroupPeople();toast('Group-scoped role removed. Independent user grants retained.')})}
function addGroupUsers(role){if(!can('assets.manage')||!editableAssetGroup(assetsData.selected))return;const g=assetsData.groups.find(g=>g.id===assetsData.selected),def=groupRoleDefinitions[role];const channels=assetsData.channels.filter(c=>c.assetGroup===g.id&&accountAllowed(c.id));assetModal('Add '+def.label.toLowerCase(),`<form id="group-people-form"><p class="form-description">${safe(g.name)}. Select staff, then explicitly select the accounts covered by this role.</p><div class="field"><label for="group-user-search">Search staff</label><input id="group-user-search" placeholder="Search name…"></div><div class="resource-list" id="group-user-choices">${accessUsers.map(u=>`<label class="resource-option" data-group-user-name="${safe(u.name.toLowerCase())}"><input type="checkbox" name="group-role-user" value="${u.id}"><span><strong>${safe(u.name)}</strong><small>${safe(u.email)}</small></span></label>`).join('')}</div><h3>${role==='ads'?'Ad accounts':'Social channels'}</h3>${role==='ads'?'<div class="connection-boundary"><strong>No ad accounts linked to this Asset Group yet.</strong><p>The role can be recorded, but it grants no ad-account access until specific accounts are assigned.</p></div>':`<div class="resource-list">${channels.map(c=>`<label class="resource-option"><input name="group-role-channel" type="checkbox" value="${c.id}">${channelAvatar(c)}<span><strong>${safe(c.name)}</strong><small>${c.network}</small></span></label>`).join('')||'<p>No channels linked. Role will grant no account access.</p>'}</div>`}<p class="ops-muted">No accounts are selected by default. Group roles do not grant publishing authority or advertising spend authorization.</p><div class="form-actions"><button class="btn" type="button" data-close>Cancel</button><button class="btn primary" type="submit">Assign role & selected accounts</button></div></form>`);document.querySelector('#group-user-search').oninput=e=>document.querySelectorAll('[data-group-user-name]').forEach(l=>l.style.display=l.dataset.groupUserName.includes(e.target.value.toLowerCase())?'':'none');document.querySelector('#group-people-form').onsubmit=e=>{e.preventDefault();const users=[...document.querySelectorAll('[name="group-role-user"]:checked')].map(i=>i.value),channelIds=[...document.querySelectorAll('[name="group-role-channel"]:checked')].map(i=>i.value);if(!users.length){toast('Select at least one user.');return}g.userAssignments=g.userAssignments||[];for(const userId of users){const prior=g.userAssignments.find(a=>a.userId===userId&&a.role===role);if(prior)prior.channelIds=[...new Set([...prior.channelIds,...channelIds])];else g.userAssignments.push({id:crypto.randomUUID(),userId,role,channelIds:role==='ads'?[]:channelIds,adAccountIds:[]})}persistAssets();logOps('Asset-group role assigned',g.name+'; '+def.label+'; '+users.length+' user(s), '+(role==='ads'?0:channelIds.length)+' selected accounts.');close();renderGroupPeople();toast('Role assigned within this Asset Group only.')}}
const masterBeforeVoiceInvalidation=enhanceMasterBrand;enhanceMasterBrand=function(board){masterBeforeVoiceInvalidation(board);const form=document.querySelector('#master-brand-form'),submit=form.onsubmit;form.onsubmit=e=>{const before=JSON.stringify(board.master);submit(e);if(before!==JSON.stringify(board.master)){(board.voices||[]).forEach(v=>v.reviewed=false);saveOps()}}};
const mediaCreditsBeforeScope=postMarkup;postMarkup=function(p){let markup=mediaCreditsBeforeScope(p);if(p.mediaAssetId){const asset=mediaData.assets.find(a=>a.id===p.mediaAssetId);if(asset?.source)markup=markup.replace('User-selected local demo image. No external upload.',`Media storage sample: <a href="${asset.source}" target="_blank" rel="noopener noreferrer">${safe(asset.credit)}</a> · illustrative location`)}return markup};
const saveComposerBeforeLibrary=saveComposerPosts;saveComposerPosts=function(status){if(singleDraft?.mediaAssetId){const a=mediaData.assets.find(a=>a.id===singleDraft.mediaAssetId);if(!a||!mayBrowseMedia(a)||a.trashed||a.status!=='Approved'){toast('Selected media is unavailable or needs review. Choose approved media.');return}}saveComposerBeforeLibrary(status)};
if(location.hash.startsWith('#media=')&&pageAllowed('media')){renderWorkspace('media');openMediaDetails(decodeURIComponent(location.hash.slice(7)))}
